def _decode_cursor(cursor):
    if cursor is None:
        return 0
    value = int(cursor)
    if value < 0:
        raise ValueError("cursor must be non-negative")
    return value


def _encode_cursor(offset):
    return str(offset)


def _next_offset(offset, returned, total):
    if returned == 0 or offset + returned >= total:
        return None
    return offset + returned + 1


def fetch_page(items, cursor=None, limit=3):
    if limit <= 0:
        raise ValueError("limit must be positive")
    offset = _decode_cursor(cursor)
    chunk = list(items[offset:offset + limit])
    next_offset = _next_offset(offset, len(chunk), len(items))
    next_cursor = None if next_offset is None else _encode_cursor(next_offset)
    return chunk, next_cursor

